   for(unsigned k=0;k<60;++k){in.yaw+=.012;step();require(footfloor()>-.014,"yaw-in-place grounded soles");}for(unsigned k=0;k<60;++k)step();neutral("after stationary turn");
   // Whole-body reversals use the displayed pose and settle cleanly.
