   in.yaw=0;for(unsigned k=0;k<45;++k)step();unsigned run_clip=0;for(unsigned k=0;k<h.asset().clips.size();++k)if(h.asset().clips[k].name=="Story_UnarmedRunFull")run_clip=k;
   double walk_duration=0;for(const auto&clip:h.asset().clips)if(clip.name=="Story_UnarmedWalkFull")walk_duration=clip.duration;
   const double captured_walk=walk_stride[c]/walk_duration,captured_run=run_stride[c]/h.asset().clips[run_clip].duration;
   in.dz=3.5*in.dt;for(unsigned k=0;k<180;++k){const double before=h.stats().full_unarmed_cycles,w=h.stats().full_unarmed_run_blend,goal=std::clamp((3.5-captured_walk)/(captured_run-captured_walk),0.,1.),response=goal<w?.045:.075;double integral=0;for(unsigned q=0;q<256;++q){const double t=in.dt*(q+.5)/256,blend=goal+(w-goal)*std::exp(-t/response);integral+=1/(walk_stride[c]+(run_stride[c]-walk_stride[c])*blend);}const double expected=3.5*in.dt*integral/256;step();const double err=std::abs((h.stats().full_unarmed_cycles-before)-expected);max_phase_integral_error=std::max(max_phase_integral_error,err);require(err<.0000002,"actual distance uses linearly blended full-body stride integral");}
   min_medium_run_blend=std::min(min_medium_run_blend,double(h.stats().full_unarmed_run_blend));max_medium_run_blend=std::max(max_medium_run_blend,double(h.stats().full_unarmed_run_blend));require(h.stats().full_unarmed_run_blend>.35&&h.stats().full_unarmed_run_blend<.50,"3.5m/s stays an intermediate human walk/run mix");
   in.dz=0;for(unsigned k=0;k<150;++k)step();require(h.stats().full_unarmed_run_blend<.00001,"stopped body releases run blend");neutral("after medium run");g.sx=.04;g.sz=.055;in.reset=true;step();for(unsigned k=0;k<90;++k)step();require(footfloor()>-.012&&footfloor()<.04,"actual quiet soles fit a gentle slope");for(unsigned k=0;k<180;++k){in.dt=k%4==0?1./30:k%4==1?1./120:k%4==2?1./45:1./60;in.dx=.7*in.dt;in.dz=1.2*in.dt;step();if(k%10==0)require(footfloor()>-.02,"variable-dt sloped walk clearance");}in.dt=1./60;in.dx=in.dz=0;
